package run.ikaros.notes; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PrivateVaultSecurityService{private final PrivateVaultRepository vaults;private final PrivateNoteRepository notes;public PrivateVaultSecurityService(PrivateVaultRepository v,PrivateNoteRepository n){vaults=v;notes=n;}public Mono<VaultView> rotateRecoveryKey(UUID a,UUID id,UpdateRecoveryKeyRequest q){return own(a,id).flatMap(v->vaults.save(new PrivateVaultEntity(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),q.encryptedRecoveryKey(),v.status(),v.createdAt(),Instant.now(),v.version()))).map(this::view);}public Mono<PrivateVaultExport> export(UUID a,UUID id){return own(a,id).flatMap(v->notes.findAllByVaultIdAndOwnerIdAndUpdatedAtGreaterThanOrderByUpdatedAtAsc(id,a,Instant.EPOCH).collectList().map(xs->new PrivateVaultExport(v.id(),v.securityProfile(),v.cryptoContext(),v.encryptedRecoveryKey(),xs.stream().map(this::note).toList())));}private Mono<PrivateVaultEntity> own(UUID a,UUID id){return vaults.findById(id).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Private Vault 不存在或无权访问")));}private VaultView view(PrivateVaultEntity v){return new VaultView(v.id(),v.ownerId(),v.name(),v.securityProfile(),v.cryptoContext(),v.status(),v.createdAt());}private NoteView note(PrivateNoteEntity n){return new NoteView(n.id(),n.vaultId(),n.notebookId(),n.encryptedTitle(),n.encryptedBody(),n.encryptedProperties(),n.revision(),n.tombstone(),n.createdAt(),n.updatedAt());}}
